func (p *portEntry) containerPortNum() string {
	if idx := strings.Index(p.containerPort, "/"); idx > 0 {
		return p.containerPort[:idx]
	}
	return p.containerPort
}

// mappingArg returns the "-p host:container" argument value for docker run.
